"""Read-only evidence comparison workbench; no generated clinical conclusions."""

def page():return HTML

HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Evidence workbench</title>
<style>:root{color-scheme:dark;background:#10151b;color:#e8f1f4;font-family:Inter,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0}main{max-width:1250px;padding:40px 24px;margin:auto}.eyebrow{color:#92d7c6;font:12px monospace;letter-spacing:2px}h1{font-weight:450;font-size:clamp(32px,5vw,56px);letter-spacing:-2px;max-width:850px}p{line-height:1.6;max-width:850px;color:#b2c3cf}a{color:#97dccb}nav{display:flex;gap:24px;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:32px 0}.card{background:#19242d;border:1px solid #364650;border-radius:12px;padding:24px;display:flex;flex-direction:column;align-items:start}.card h2{font-size:19px;line-height:1.4;font-weight:500}.card p{font-size:14px;flex:1}.card button,button{background:#b3e6d7;color:#152f2c;border:0;border-radius:6px;padding:12px 16px;cursor:pointer;font:inherit}#status{color:#b3e6d7}.number{font-size:48px;letter-spacing:-2px;font-weight:450}.patient{border-top:1px solid #364650;padding:24px 0}.patient h3{font:15px monospace;color:#9dddcc}.check{border-left:3px solid #52766f;padding:0 0 0 18px;margin:18px 0}pre{font:13px/1.6 monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#19242d;padding:18px;border-radius:8px}summary{cursor:pointer;color:#b9c9d2}.notice{border:1px solid #6c6048;padding:18px;border-radius:8px;color:#d9c598}input{width:100%;background:#19242d;color:#e8f1f4;border:1px solid #526370;border-radius:8px;padding:16px;font:16px/1.5 system-ui}#ask-form{display:grid;gap:12px;margin-top:28px}#ask-form button{justify-self:start}.interpretation{background:#182a27;border:1px solid #49756b;padding:20px;border-radius:8px;margin:18px 0}.examples{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.examples button{background:#24333f;color:#c9e8e0;font-size:13px;text-align:left}textarea{width:100%;min-height:220px;background:#19242d;color:#e8f1f4;border:1px solid #526370;border-radius:8px;padding:15px;font:13px/1.5 monospace}.muted{font-size:13px;color:#95a9b9}</style>
<main><div class="eyebrow">AGERE / RECORDED EVIDENCE</div><h1>Ask where the records agree.<br>See where they leave a question.</h1><p>Compare structured observations with the reader’s narrative annotations. Every result opens to its source. A missing record stays a missing record—it does not establish missing care.</p><nav><a href="/reader">Inspect the reader</a><a href="/">Clinical workflow review</a></nav><p class="notice">Synthetic research workspace. Text labels are unvalidated model proposals. These queries find documentation patterns, not confirmed care gaps, treatment indications or program eligibility.</p><form id="ask-form"><label for="question">Ask about recorded evidence</label><input id="question" name="question" maxlength="2000" placeholder="Find patients with historical EF in notes but no current EF annotations." autocomplete="off"><button type="submit">Ask Agere</button></form><p class="muted">Understands supported evidence phrases and combinations. Extra clinical, demographic or timing constraints are never silently dropped.</p><div id="question-examples" class="examples"></div><section id="interpretation" aria-live="polite"></section><section class="grid" id="catalog"></section>
<details><summary>Inspect or edit the explicit evidence plan</summary><p class="muted">This executes a bounded evidence schema. Supported evidence questions compile to this plan. Unrestricted clinical questions and inferred medical criteria are not supported here.</p><textarea id="plan" aria-label="Evidence query plan"></textarea><button id="run">Run evidence plan</button></details>
<p id="status" role="status" aria-live="polite"></p><section id="result"></section></main>
<script>
const $=id=>document.getElementById(id);const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
let requestSequence=0;
function render(d,title){$('result').replaceChildren(node('h2',title),node('div',d.patients_matching_evidence_plan.toLocaleString(),'number'),node('p','synthetic patients match these recorded-evidence predicates. '+d.scope));for(const patient of d.patients){const item=node('article',undefined,'patient');item.append(node('h3',patient.patient_id));for(const c of patient.evidence_checks){const check=node('div',undefined,'check');check.append(node('p',`${c.clause.source} · ${c.clause.concept} · ${c.clause.observation.replaceAll('_',' ')}: ${c.matching_evidence_occurrences} matching records`),node('p',c.meaning,'muted'));for(const example of c.examples){const evidence=example.recorded_evidence;const detail=node('details');detail.append(node('summary',example.evidence_id));if(evidence.input)detail.append(node('pre',evidence.input.text));detail.append(node('pre',JSON.stringify(evidence.fact||evidence.source,null,2)),node('p',evidence.authority,'muted'));check.append(detail)}item.append(check)}$('result').append(item)}if(!d.patients.length)$('result').append(node('p','No recorded-evidence matches. This does not establish absence of clinical need.'));$('status').textContent=`${d.cache_hit?'Cached':'Executed'} in ${d.elapsed_seconds.toFixed(4)} seconds · ${d.new_paid_api_calls} paid model calls · Showing ${d.patients.length} of ${d.patients_matching_evidence_plan} matches.`}
async function run(plan,title='Explicit evidence plan'){const seq=++requestSequence;try{$('interpretation').replaceChildren();$('result').replaceChildren();$('status').textContent='Comparing indexed evidence…';$('plan').value=JSON.stringify(plan,null,2);const r=await fetch('/api/evidence-query?plan='+encodeURIComponent(JSON.stringify(plan)));if(!r.ok)throw Error('Evidence plan rejected or index unavailable ('+r.status+')');const d=await r.json();if(seq!==requestSequence)return;render(d,title)}catch(e){if(seq===requestSequence)$('status').textContent=e.message}}
async function ask(question){const seq=++requestSequence;try{$('result').replaceChildren();$('interpretation').replaceChildren();$('plan').value='';$('status').textContent='Interpreting the complete evidence question…';const r=await fetch('/api/evidence-ask?q='+encodeURIComponent(question));if(!r.ok)throw Error('Question rejected ('+r.status+')');const d=await r.json();if(seq!==requestSequence)return;const box=node('div',undefined,'interpretation');if(!d.result){box.append(node('h2','This question was not executed'),node('p',d.reason));if(d.unmatched_text)box.append(node('pre',d.unmatched_text));$('interpretation').append(box);$('status').textContent='No partial query or paid model call was made.';return}$('plan').value=JSON.stringify(d.plan,null,2);box.append(node('h2','Interpreted as '+(d.combination==='all'?'all':'any')+' of these evidence conditions'));const list=node('ul');for(const text of d.interpretation)list.append(node('li',text));box.append(list,node('p','This is an interpretation of recorded evidence, not a clinical eligibility or treatment decision.','muted'));$('interpretation').append(box);render(d.result,question)}catch(e){if(seq===requestSequence)$('status').textContent=e.message}}
$('ask-form').onsubmit=e=>{e.preventDefault();ask($('question').value)};
$('run').onclick=()=>{try{run(JSON.parse($('plan').value))}catch(e){++requestSequence;$('result').replaceChildren();$('interpretation').replaceChildren();$('status').textContent='Enter a valid JSON evidence plan.'}};
fetch('/api/evidence-catalog').then(r=>{if(!r.ok)throw Error('Evidence index unavailable');return r.json()}).then(d=>{for(const text of (d.question_examples||[]).slice(0,4)){const button=node('button',text);button.onclick=()=>{$('question').value=text;ask(text)};$('question-examples').append(button)}for(const q of d.queries){const card=node('article',undefined,'card');card.append(node('h2',q.title),node('p',q.why));const button=node('button','Inspect this pattern');button.onclick=()=>run(q.plan,q.title);card.append(button);$('catalog').append(card)}$('plan').value=JSON.stringify(d.queries[0].plan,null,2)}).catch(e=>$('status').textContent=e.message);
</script></html>'''
